package i18n

import "strings"

// SecurityText localizes normalized security-domain text. Docker property
// names, IDs, paths, image references, and other evidence remain unchanged.
func SecurityText(language, value string) string {
	language = Normalize(language)
	if language == "en-US" {
		return value
	}
	translated, ok := securityTexts[value]
	if ok {
		if language == "es" {
			return translated[1]
		}
		return translated[0]
	}
	for source, replacements := range securityTextFragments {
		replacement := replacements[0]
		if language == "es" {
			replacement = replacements[1]
		}
		value = strings.ReplaceAll(value, source, replacement)
	}
	return value
}

